</td></tr><?php endforeach?></tbody></table></div></section><?php endif?>
<script>document.addEventListener('DOMContentLoaded',function(){var session=document.getElementById('session_id'),exam=document.getElementById('exam_id');function filterExams(){if(!session||!exam)return;Array.prototype.forEach.call(exam.options,function(o){if(!o.value)return;o.hidden=!!session.value&&o.getAttribute('data-session')!==session.value;});if(exam.selectedOptions.length&&exam.selectedOptions[0].hidden)exam.value='';}if(session)session.addEventListener('change',filterExams);filterExams();});</script>
